/** Independent SSR reader: actual visible cells,text and wire geometry. */
import assert from'node:assert/strict';import{legacy2019InspectionReview as r}from'./legacy-2019-pm-inspection-review';
export const inspectionDecode=(s:string)=>s.replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#x27;|&#39;/g,"'").replace(/&#x([0-9a-f]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16))).replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(Number(n)));
const attrs=(s:string)=>Object.fromEntries([...s.matchAll(/([\w-]+)="([^"]*)"/g)].map(m=>[m[1].toLowerCase(),inspectionDecode(m[2])]));
export function inspectionTableGrid(html:string){
 const head=html.match(/<thead>([\s\S]*?)<\/thead>/)![1],body=html.match(/<tbody>([\s\S]*?)<\/tbody>/)![1],rows=[...body.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/g)],grid:string[][]=[],spans:{v:string;left:number}[]=[];
 for(const row of rows){const cells=[...row[1].matchAll(/<(th|td)([^>]*)>([\s\S]*?)<\/\1>/g)],out:string[]=[];let x=0;const inherited=()=>{while(spans[x]?.left>0){out[x]=spans[x].v;spans[x].left--;x++;}};for(const c of cells){inherited();const a=attrs(c[2]),col=Number(a.colspan??1),rowspan=Number(a.rowspan??1),v=inspectionDecode(c[3]);for(let j=0;j<col;j++){out[x]=v;if(rowspan>1)spans[x]={v,left:rowspan-1};x++;}}inherited();grid.push(out);}
 return{headRows:[...head.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/g)].map(m=>[...m[1].matchAll(/<th([^>]*)>([\s\S]*?)<\/th>/g)].map(c=>({text:inspectionDecode(c[2]),attrs:attrs(c[1])}))),grid};
}
export function assertLegacy2019InspectionFigure(html:string,profile:string){
 const name=profile.replace('legacy-2019-inspection-','');assert(!/<button\b/.test(html),'source figures must not create operation controls');
 if(['api-table','product-report','results-list'].includes(name)){
  const tables=[...html.matchAll(/<table\b[^>]*>([\s\S]*?)<\/table>/g)];assert.equal(tables.length,1);const t=inspectionTableGrid(tables[0][0]);assert.equal(t.headRows.length,1);
  if(name==='api-table'){assert.deepEqual(t.headRows[0].map(c=>c.text),['サーバ','WebAPI名','WebAPI仕様']);assert.equal(t.headRows[0][2].attrs.colspan,'2');assert.deepEqual(t.grid,r.apis.flatMap(a=>[[a.server,a.name,'引数',a.args.join('、')],[a.server,a.name,'戻り値',a.returns],[a.server,a.name,'処理',a.processing]]));assert(inspectionDecode(html).includes(r.table1.note));assert.deepEqual([...html.matchAll(/rowSpan="(\d+)"/g)].map(m=>Number(m[1])),[12,3,3,3,3,9,3,3,3]);return{tables:1,bodyRows:21,logicalCells:84};}
  if(name==='product-report'){const f=r.page27.figure3;assert.deepEqual(t.headRows[0].map(c=>c.text),['',...f.columns]);assert.deepEqual(t.grid,f.rows.map((v,i)=>[String(i+1),...v]));const dt=[...html.matchAll(/<dt>([\s\S]*?)<\/dt>/g)].map(m=>inspectionDecode(m[1])),dd=[...html.matchAll(/<dd>([\s\S]*?)<\/dd>/g)].map(m=>inspectionDecode(m[1]));assert.deepEqual(dt,['検査農産物ID','検査農産物名',...Object.keys(f.offerer)]);assert.deepEqual(dd,[f.productId,f.productName,...Object.values(f.offerer)]);return{tables:1,bodyRows:5,logicalCells:25};}
  const f=r.page28and29.figure4;assert.deepEqual(t.headRows[0].map(c=>c.text),[...f.columns]);assert.deepEqual(t.grid,Array.from({length:10},(_,i)=>i===0?[...f.firstRow]:[String(i+1),...Array<string>(6).fill('⋮')]));assert(inspectionDecode(html).includes('開始番号：1　前へ　次へ'));assert(inspectionDecode(html).includes(f.note));return{tables:1,bodyRows:10,logicalCells:70};
 }
 assert(['architecture','entities'].includes(name));assert.equal((html.match(/<svg\b/g)??[]).length,1);assert(html.includes('aria-describedby='));const desc=inspectionDecode(html.match(/<desc[^>]*>([\s\S]*?)<\/desc>/)![1]),texts=[...html.matchAll(/<text([^>]*)>([\s\S]*?)<\/text>/g)].map(m=>({a:attrs(m[1]),text:inspectionDecode(m[2])}));
 if(name==='entities'){const fields=texts.filter(t=>t.a['data-field']);assert.deepEqual(fields.map(t=>t.text),r.page25.figure2.entities.flatMap(e=>[...e.fields]));assert.equal(fields.filter(t=>t.a['text-decoration']==='underline').length,5);for(const e of r.page25.figure2.entities){assert(texts.some(t=>t.text===e.name));assert(desc.includes(e.name));e.fields.forEach(f=>assert(desc.includes(f)));}assert.deepEqual(fields.filter(t=>t.a['text-decoration']==='underline').map(t=>t.text),r.page25.figure2.entities.map(e=>e.primaryKey));assert.equal((html.match(/data-entity=/g)??[]).length,5);assert.equal((html.match(/<rect\b/g)??[]).length,7);assert.equal((html.match(/data-wire-/g)??[]).length,0);assert(!desc.includes('外部キー'));assert(desc.includes('［b］')&&desc.includes('［c］'));return{svg:1,texts:texts.length,fields:18,primary:5,wires:0};}
 const servers=r.page24.figure1.servers,visible=[...servers.flatMap(s=>[s.tool,s.server,s.db,s.api]),'報告用アプリケーション','凡例　→：アクセスを示す。記載がないアクセスは発生しない。'];assert.deepEqual(texts.map(t=>t.text).sort(),visible.sort());assert(desc.includes(r.page24.figure1.legend));
 const wires=[...html.matchAll(/<path([^>]*data-wire-from[^>]*)>/g)].map(m=>attrs(m[1]));assert.equal(wires.length,8);assert.deepEqual(wires.map(w=>[w['data-wire-from'],w['data-wire-to']]).sort(),r.page24.figure1.accessEdges.map(e=>[...e]).sort());
 const points=(d:string)=>{let x=0,y=0;const out:number[][]=[];for(const m of d.matchAll(/([MLHV])([^MLHV]+)/g)){const n=m[2].trim().split(/[ ,]+/).map(Number);if(m[1]==='M'||m[1]==='L'){x=n[0];y=n[1];}else if(m[1]==='H')x=n[0];else y=n[0];out.push([x,y]);}return out;};
 const boxes=[...html.matchAll(/<rect([^>]*data-box-name[^>]*)>/g)].map(m=>attrs(m[1]));
 for(const w of wires){const p=points(w.d),start=p[0],end=p.at(-1)!,from=boxes.find(b=>b['data-box-name']===w['data-wire-from']),to=boxes.find(b=>b['data-box-name']===w['data-wire-to']);assert(from&&to);const sy=Number(from.y)+(w['data-wire-from']==='報告用アプリケーション'?0:Number(from.height)),ty=Number(to.y)+(w['data-wire-to'].includes('.')?Number(to.height):0);assert.equal(start[1],sy);assert.equal(end[1],ty);assert(start[0]>Number(from.x)&&start[0]<Number(from.x)+Number(from.width));assert(end[0]>Number(to.x)&&end[0]<Number(to.x)+Number(to.width));}
 return{svg:1,texts:texts.length,wires:8};
}
